contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address _target, uint _value, bytes memory _data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value);
        require(_value > 0);
        require(_target != address(this));
        require(_target != address(0));
        uint targetBefore = _target.balance;
        uint cBefore = address(c).balance;
        c.sendMoney(_target, _value, _data); if (__ESBMC_reverted()) return;
        uint targetAfter = _target.balance;
        assert(targetAfter == targetBefore + _value && address(c).balance == cBefore - _value);
    }
    receive() external payable {}
}

